draw:
var g = 9.8;
var m1 = p.m1, m2 = p.m2;
var a = (m1 - m2) * g / (m1 + m2);
var T = 2 * m1 * m2 * g / (m1 + m2);

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var cx = W * 0.5;
var cy = H * 0.16;
var R = Math.min(W, H) * 0.07;
var half = W * 0.20;
var rest = H * 0.55;
var span = H * 0.22;

// animate: let the heavier side fall, then loop
var cycle = 2.6;
var s = t % cycle;
var d = 0.5 * a * s * s;
var maxd = span;
if (d > maxd) { d = maxd; }
if (d < -maxd) { d = -maxd; }

var y1 = rest + d;
var y2 = rest - d;

// ceiling bracket
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(cx - W * 0.12, cy - R - 14);
ctx.lineTo(cx + W * 0.12, cy - R - 14);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx, cy - R - 14);
ctx.lineTo(cx, cy - R);
ctx.stroke();

// pulley
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.arc(cx, cy, R, 0, Math.PI * 2);
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(cx, cy, 2.5, 0, Math.PI * 2);
ctx.fill();

// rope
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(cx - R, cy);
ctx.lineTo(cx - R, y1);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx + R, cy);
ctx.lineTo(cx + R, y2);
ctx.stroke();
ctx.beginPath();
ctx.arc(cx, cy, R, Math.PI, 0, true);
ctx.stroke();

// blocks, area scaled with mass
function block(x, y, m, name) {
  var w = 22 + m * 3.2;
  var h = 16 + m * 1.6;
  ctx.fillStyle = C.figure;
  ctx.globalAlpha = 0.25;
  ctx.fillRect(x - w / 2, y, w, h);
  ctx.globalAlpha = 1;
  ctx.strokeStyle = C.ink;
  ctx.strokeRect(x - w / 2, y, w, h);
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  ctx.fillText(name + " = " + m.toFixed(1) + " kg", x, y + h + 14);
}
block(cx - R, y1, m1, "m1");
block(cx + R, y2, m2, "m2");

// tension arrows on the ropes
ctx.strokeStyle = C.ink;
ctx.fillStyle = C.ink;
function up(x, y, len) {
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x, y - len);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x, y - len);
  ctx.lineTo(x - 4, y - len + 7);
  ctx.lineTo(x + 4, y - len + 7);
  ctx.closePath();
  ctx.fill();
}
up(cx - R, y1 - 4, 26);
up(cx + R, y2 - 4, 26);
ctx.textAlign = "right";
ctx.fillText("T", cx - R - 7, y1 - 20);
ctx.textAlign = "left";
ctx.fillText("T", cx + R + 7, y2 - 20);

// acceleration direction marker
ctx.fillStyle = C.accent;
ctx.textAlign = "center";
var dirTxt = a > 0.02 ? "m1 falls" : (a < -0.02 ? "m2 falls" : "balanced");
ctx.fillText(dirTxt, cx, H - 8);

out.note = "a = " + Math.abs(a).toFixed(2) + " m/s^2,  T = " + T.toFixed(1) +
  " N   (m1 g = " + (m1 * g).toFixed(1) + " N, m2 g = " + (m2 * g).toFixed(1) + " N)";
